5296f17be7fcb4cd283b6c867177d4a88f9ce5ec.template:
PLUGIN_ROOT=$(python "${CLAUDE_PLUGIN_ROOT}/bin/resolve_plugin_root.py" --plugin-name foundry) || exit $?; export PLUGIN_ROOT
MANAGE_TPL=$(python "$PLUGIN_ROOT/bin/resolve_skill_subdir.py" manage templates) || { printf "! BREAKING: manage templates not found — run /foundry:setup first\n"; exit 1; }
echo "Template dir: $MANAGE_TPL"

a0eb37734c6d38a07b4bad613f772031e0acab2b.template:
PLUGIN_ROOT=$(python "${CLAUDE_PLUGIN_ROOT}/bin/resolve_plugin_root.py" --plugin-name foundry) || exit $?; export PLUGIN_ROOT
BRIDGE_ROOT=$(python "$PLUGIN_ROOT/bin/get_plugin_install_path.py" borda-ai-rig bridge 2>/dev/null) || BRIDGE_ROOT=""
[ -n "$BRIDGE_ROOT" ] && [ -d "$BRIDGE_ROOT" ] || { printf "  bridge: skipped (not installed)\n"; exit 0; }
python "$PLUGIN_ROOT/bin/settings_json.py" enable-plugin ~/.claude/settings.json --name "bridge@borda-ai-rig" || { printf "! failed updating enabledPlugins — settings.json unchanged\n"; exit 1; }
